    kpiCtx.cols = tb.rows.length ? tb.rows[0].cells.length : 1;
    kpiTotalRow = document.createElement("tr"); kpiTotalRow.className = "rv-kpi-total";
    kpiTotalRow.appendChild(document.createElement("td"));
    tb.appendChild(kpiTotalRow);
