    function upd() {
      var over = strip.scrollWidth > strip.clientWidth + 2;
      prev.style.display = next.style.display = over ? "" : "none";
      prev.disabled = strip.scrollLeft <= 1;
      next.disabled = strip.scrollLeft + strip.clientWidth >= strip.scrollWidth - 2;
    }
    prev.addEventListener("click", function () { strip.scrollBy({ left: -Math.round(strip.clientWidth * 0.8), behavior: "smooth" }); });
    next.addEventListener("click", function () { strip.scrollBy({ left: Math.round(strip.clientWidth * 0.8), behavior: "smooth" }); });
    strip.addEventListener("scroll", upd);
    wrap.appendChild(prev); wrap.appendChild(strip); wrap.appendChild(next);
