    th.appendChild(rmkEl("div", "rv-rmks-text" + (data.report_remark ? "" : " rv-rmks-none"),
      data.report_remark || (beh ? "They didn't submit." : "They wrote no overall remark.")));
    grid.appendChild(th);
    var mine = rmkEl("div", "rv-rmks-block rv-rmks-mine");
