      var jw = rmkEl("span", "rv-cal-just"); jw.setAttribute("data-tone", tone);
      jw.textContent = (JUST_GLYPH[k.justified] ? JUST_GLYPH[k.justified] + " " : "") + (JUST_SHORT[k.justified] || DASH);
