        var v = x.weight + "% · " + (!x.locked ? "Not locked yet" : kept ? "Kept " + nm(x.band)
          : bc.came_in ? "Moved " + nm(bc.came_in) + " → " + nm(x.band) : "Set " + nm(x.band));
        journeyRow(box, x.who, v, x.locked ? x.band : null, !x.locked ? "is-wait" : kept ? "rv-bd-cal"
          : "rv-bd-cal is-moved", null, x.who + (x.title ? ", " + x.title : "") + " · calibrates them at BU level, "
          + x.weight + "% of the call");
