      var sn = rmkEl("span", "rv-cal-soft rv-cal-selfnote", d && d.mid_year ? "Set by your HOD" : "Set by BU CEO");
      sn.title = d && d.mid_year ? "Your own band: your own HOD reviews it, not you" : "Your own band: your BU CEO reviews it, not you";
