    var card = document.createElement("div"); card.className = "modal-card rv-dr-assign";
    card.setAttribute("role", "alertdialog"); card.setAttribute("aria-modal", "true");
    var h = document.createElement("h2"); h.id = "rv-dr-assign-h"; h.textContent = "Set these bands first";
    card.setAttribute("aria-labelledby", h.id); card.appendChild(h);
