    var nm = key === "NF" ? "Not finalised" : (key ? (lbl[key] || key) : "no band yet");
    var dn = rmkEl("span", "rv-tbox-dn", (key === "NF" ? "Also not finalised" : key ? "Also at " + nm
      : "Also with no band yet") + " · " + same.length);
    dn.title = dn.textContent; bx.appendChild(dn);
