        b.setAttribute("aria-pressed", on ? "true" : "false");
        b.title = pot + " potential · " + pf + " performance" + (cat[k] ? " · " + cat[k] : "");
        b.appendChild(rmkEl("b", null, String(n[k] || 0)));
