    wrap.appendChild(rmkEl("span", "rv-grp-9y", ""));
    ["Low UA · BE", "Mid ME", "High AE · OU"].forEach(function (x) { wrap.appendChild(rmkEl("span", "rv-grp-9x", x)); });
    return wrap;
