    var phCount = rmkEl("span", "rv-ph-tbcount", [d.group ? (d.company_label || "") + (d.pick_words ? d.pick_words.map(function (w) { return " \u00b7 " + w; }).join("") : "") : "",
      (d.group || !d.company) ? "" : tbPat(d.pat), d.placed + " placed" + ((d.unplaced || []).length ? " \u00b7 " + d.unplaced.length + " not placed yet" : "")].filter(Boolean).join(" \u00b7 "));
    phCount.hidden = true; bar.appendChild(phCount);
