    var dl = document.createElement("a"); dl.className = "od-btn-nv is-outline ec-dl"; dl.textContent = d.download_label || "Download";
    dl.href = d.download_url + (d.bg || d.company ? "?" + (d.bg ? "bg=" + encodeURIComponent(d.bg) : "")
      + (d.company ? (d.bg ? "&" : "") + "company=" + encodeURIComponent(d.company) : "") : "");
    dl.setAttribute("download", "");
    if (d.not_released) dl.style.display = "none";
    bar.appendChild(dl);
    box.appendChild(bar);
    box.appendChild(rmkEl("p", "ec-note", (d.status_text || "") + (d.released_text ? " \u00b7 " + d.released_text : "")));
    if (d.show) {   // an insight link narrowed the box: say so, and one click shows everyone again
      var sh = rmkEl("p", "ec-show"); sh.setAttribute("data-chair-show", d.show.key);
      sh.appendChild(rmkEl("span", "", d.show.label + " \u00b7 " + d.show.n + (d.show.n === 1 ? " person" : " people")));
      var shb = document.createElement("button"); shb.type = "button"; shb.className = "od-linkbtn"; shb.textContent = "Show everyone";
      shb.addEventListener("click", function () { chairClearShow(); });
      sh.appendChild(shb); box.appendChild(sh);
    }
    // BG row: all business groups, then each
