    (d.bgs || []).forEach(function (g) {
      bgPills.push(chairPill(g.label, g.released && g.n != null ? String(g.n) : null, d.bg === g.key,
        g.released ? g.label + " · " + g.n + " placed" : g.label + " · not released yet", false,
        function () { chairSelectBg(g.key); }));
    });
    box.appendChild(chairPills("BG", bgPills, "Business group"));
    // BU row: one group's units; with none picked it says what to do
    if (d.bg && (d.companies || []).length) {
      var buPills = [chairPill("All units", null, !d.company, "Every unit of " + d.company_label, false, function () { chairSelectBu(""); })];
      d.companies.forEach(function (c) {
        buPills.push(chairPill(c.label, String(c.n), d.company === c.key,
          c.label + " · " + c.n + " placed" + (c.locked ? " · locked by the BG CEO" : " · not locked yet"), c.locked,
          function () { chairSelectBu(c.key); }));
      });
      box.appendChild(chairPills("BU", buPills, "Business unit"));
    } else {
      var hint = rmkEl("div", "rv-tbox-busrow");
      hint.appendChild(rmkEl("span", "rv-grp-flbl rv-tbox-rowlbl", "BU"));
      hint.appendChild(rmkEl("span", "ec-bu-hint", d.bg ? "No units to show." : "Pick one group to narrow to its units"));
      box.appendChild(hint);
    }
    // the filter line (Chris, 2026-11-02, canvas board F): the filters the super admin ticked for him, once a business group is picked,
    // counted within it (and the unit); with All business groups only a muted line saying what to do
    var efl = d.not_released ? null : tbFilterLine(d);
    if (efl) box.appendChild(efl);
    else if (d.filter_hint && !d.not_released) {
      var eh = rmkEl("div", "rv-tbox-filter is-hint"); eh.appendChild(rmkEl("span", "rv-cal-fhint", d.filter_hint));
      box.appendChild(eh);
    }
    if (d.not_released) {   // no count and no name of anyone: the scope is not released to leaders yet
      var nr = rmkEl("p", "ec-none", d.not_released_text || "Not released yet."); nr.setAttribute("role", "status");
      box.appendChild(nr);
      return box;
    }
    var body = rmkEl("div", "rv-tbox-body is-" + tb.view);
    if (tb.view === "list") body.appendChild(tbListView(d));
