  // ---- HIS LEADERS' TALENT BOX (P4, 2026-10-29; canvas boards 4 and 4b). The Talent Box card again, now his to work: ONE filter
  // row (the business groups, and Group Chiefs), the 3x3 and its people panel with Move, "Not placed yet (k)" with a Place on
  // each, Show moved, and one Lock Talent Box that waits until everyone is placed. A move or a place needs his reason (the
  // server refuses without it); his moves are drafts until he locks, and a locked box is final. A name opens their page
  // beside the box (the BG CEO's person page at his seat), whose last tab, Record, is his alone.
  function tbColOfBand(d, band) {
    var hit = "";
    (d.cols || []).forEach(function (c) { if ((c.bands || []).indexOf(band) >= 0) hit = c.key; });
    return hit;
  }
  var UNP_SHOWN = 4;   // "Not placed yet": the first rows in the list, the rest in a fold
  function chairUnplacedRow(d, x) {
    var row = rmkEl("div", "ec-unp-row");
    var nm = document.createElement("button"); nm.type = "button"; nm.className = "ec-unp-name"; nm.textContent = x.name; nm.title = "Open " + x.name + "’s page";
    nm.addEventListener("click", function () { tbOpenPerson(x); });
    row.appendChild(nm);
    var wh = rmkEl("span", "ec-unp-where", x.bu || DASH); wh.title = x.bu || ""; row.appendChild(wh);
    var why = rmkEl("span", "ec-unp-why");
    why.appendChild(rmkEl("span", "ec-unp-chip", x.need || "Awaits your rating"));
    var wy = rmkEl("span", "ec-unp-text", x.why || (x.missing || []).join(" · ")); wy.title = wy.textContent; why.appendChild(wy);
    row.appendChild(why);
    var pl = document.createElement("button"); pl.type = "button"; pl.className = "rv-tbox-mvbtn ec-unp-place"; pl.textContent = "Place";
    pl.setAttribute("data-move", String(x.id)); pl.setAttribute("aria-expanded", tb.open === x.id ? "true" : "false");
    pl.setAttribute("aria-haspopup", "dialog"); pl.setAttribute("aria-label", "Place " + x.name);
    if (tb.open === x.id) pl.classList.add("is-open");
    if (d.locked || x.locked) { pl.disabled = true; pl.title = d.locked ? "Your Talent Box is locked" : "Released to leaders: read only now"; }
    else pl.addEventListener("click", function () { if (tb.open === x.id && tbMv) tbEndMove(true); else tbStartMove(x); });
    row.appendChild(pl);
    return row;
  }
  function chairUnplaced(d) {
    // a fold, open on its own while only a few wait (the box then still fits the screen); what he picks is kept across redraws
    var list = d.unplaced || [], sec = document.createElement("details"); sec.className = "ec-unp";
    sec.open = tb.unpOpen != null ? !!tb.unpOpen : list.length <= 3;
    sec.addEventListener("toggle", function () { tb.unpOpen = sec.open; tbFit(); });
    var hd = document.createElement("summary"); hd.className = "ec-unp-hd";
    hd.appendChild(rmkEl("b", null, "Not placed yet (" + list.length + ")"));
    hd.appendChild(rmkEl("span", "ec-unp-sub", "No result to place them by: Place puts them in the box you pick"));
    sec.appendChild(hd);
    list.slice(0, UNP_SHOWN).forEach(function (x) { sec.appendChild(chairUnplacedRow(d, x)); });
    if (list.length > UNP_SHOWN) {
      var det = document.createElement("details"); det.className = "fold ec-unp-more";
      det.appendChild(rmkEl("summary", null, (list.length - UNP_SHOWN) + " more"));
      list.slice(UNP_SHOWN).forEach(function (x) { det.appendChild(chairUnplacedRow(d, x)); });
      var less = document.createElement("button"); less.type = "button"; less.className = "fold-less"; less.setAttribute("data-fold-less", "");
      less.textContent = "Show less"; det.appendChild(less);
      sec.appendChild(det);
    }
    return sec;
  }
  // the one Lock: greyed until everyone open is placed (with the reason beside it); its confirm names how many, its button
