  function tbR2Unit(d) { return d && d.round2 && d.round2.unit ? d.round2.unit : null; }
  function tbR2ReadOnlyWhy(d) {
    var u = tbR2Unit(d);
    if (d.round2 && d.round2.tab === "1") return "Calibration round 1 is your earlier box, read only: you place in Calibration round 2";
    return u && u.state === "due" ? "Round 2 closed on " + u.due + ": Group People finish it" : "The Talent Box is locked";
  }
  // a pushed unit's pill: "PAT 85% -> 62%" and where its round stands (the PAT it was locked on, then the actual)
  function tbR2Pill(d, c) {
    var r = c && c.round; if (!r || !d.round2) return null;
    var onR1 = d.round2.tab === "1" && tbR2Unit(d) && (tbR2Unit(d).members || []).indexOf(c.key) >= 0;
    if (onR1) return null;   // the Round 1 record shows the forecast figure, as locked
    var patText = "PAT " + (r.forecast || "—") + " → " + (r.actual || "—");
    var tag = rmkEl("span", "rv-tbox-r2tag is-" + r.state, r.state === "locked" ? "Round 2 ✓" : r.state === "due" ? "Closed" : "PAT updated");
    return { patText: patText, tag: tag, title: "forecast PAT " + (r.forecast || "—") + ", actual PAT " + (r.actual || "—")
      + (r.state === "locked" ? ", Round 2 locked" : r.state === "due" ? ", Round 2 closed: Group People finish it" : ", Round 2 open") };
  }
  var TB_R2_MIN_KEY = "onehr.tbox.r2bar";
