      bar.appendChild(rmkEl("span", "rv-tbox-r2k", "Round 1"));
      var t1 = "As you locked it" + (r2.r1_day ? " on " + r2.r1_day : "") + ", on the forecast PAT " + (u.forecast || "—") + " (" + (u.before || "Normal") + " curve). Read only: you place in Calibration round 2.";
      var s1 = rmkEl("span", "rv-tbox-r2say", t1); s1.title = t1; bar.appendChild(s1);
